shell_commands:
/bin/zsh -lc "python3 - <<'PY'
p='specs/hal-engine-tool-input-validation/spec.md'
s=open(p).read().replace('([validated by: rejects a wrong-typed property', '([validated by: rejects a wrong type without exposing the value](../../src/orchestration/tools/registry.privacy.test.ts#L6), [validated by: rejects a wrong-typed property')
open(p,'w').write(s)
PY
cat > src/orchestration/tools/registry.privacy.test.ts <<'EOF'
import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input privacy [specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('rejects a wrong type without exposing the value', async () => {
    const warn = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn, error: jest.fn()});
    try {
      const registry = new ToolRegistry();
      const execute = jest.fn(async () => 'executed');
      registry.register({name: 'weather', description: 'Weather', inputSchema: {
        type: 'object', properties: {location: {type: 'string'}},
      }}, execute);
      const response = await registry.execute('weather', {location: 123456789});
      expect(response.result).toMatch(/location.*string/i);
      expect(JSON.stringify({response, logs: warn.mock.calls})).not.toContain('123456789');
      expect(execute).not.toHaveBeenCalled();
      expect(warn).toHaveBeenCalledWith('tool', 'input validation failed', expect.objectContaining({
        paths: expect.arrayContaining([expect.stringMatching(/location/)]),
      }));
    } finally {
      setLogger();
    }
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.privacy.test.ts --runInBand --coverage=false"
